def _path_from_parents(net, cap):
    parent = net.parent
    to = net.g.to
    ss = net.SS
    v = net.TT
    path = []
    seen = set()
    while v != ss:
        if v in seen or len(path) > net.n + 2:
            return None
        seen.add(v)
        i = parent[v]
        if i < 0 or cap[i] <= 0:
            return None
        path.append(i)
        v = to[i ^ 1]
    path.reverse()
    return path


